// === Tab: mySketch ===
// Reference: https://www.williamrchase.com/post/strange-attractors-12-months-of-art-february/

let particles = []
let colors = []
let parameters = [] // [1.24, -1.25, -1.81, -1.91], [1.37, -1.85, -1.68, -1.38]

function setup() {
	createCanvas(windowWidth, windowHeight);
	background(255);

	// Add particles
	for (let i = 0; i < 2000; i++) {
		particles.push([random(0, width), random(0, height)])
	}

	// Add parameters
	if (parameters.length == 0) {
		for (let i = 0; i < 4; i++) {
			parameters.push(random(0, 1) + random([1, -2])) // random(-3, 3)
		}
	}

	// Add colors
	colorMode(HSL, 100);
	let mean = random(0, 100)
	for (let i = 0; i < 10; i++) {
		colors.push(abs(randomGaussian(mean, 10)) % 100)
	}
}

function draw() {
	// Display parameters
	// fill(0)
	// textSize(30)
	// text(parameters.map(x => x.toFixed(2)).join(', '), 30, 30)

	// Plot particles
	translate((width - height) / 2, 0)
	for (let i = 0; i < particles.length; i++) {
		let nextParticle = next(particles[i][0], particles[i][1])
		let x = map(particles[i][0], -3, 3, 0, height);
    let y = map(particles[i][1], -3, 3, 0, height);
		fill(colors[i % colors.length], 90, 40)
		noStroke()
		circle(x, y, 1)
		particles[i] = nextParticle
	}
}

// Move particles
function next(x, y) {
	let nx = (sin(parameters[0]*y) + parameters[2] * cos(parameters[0]*x))
	let ny = (sin(parameters[1]*x) + parameters[3] * cos(parameters[1]*y))
	return [nx, ny]
}

